def most_common_words(string):
    # Split the string into words
    words = string.split(" ")

    # Create a dictionary to store count of words
    word_counts = {}

    # Add 1 to count of every word
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1

    # Find the most common words
    sorted_words_counts = {}
    most_common_count = 0
    for word, count in word_counts.items():
        # Update the count if current count is higher
        if count > most_common_count:
            most_common_count = count
            sorted_words_counts = {word: count}
        # Add the word to the dictionary if count is same
        elif count == most_common_count:
            sorted_words_counts[word] = count

    return sorted_words_counts

