# Representing the board as a 3x3 array. 
# Empty spaces are represented with 0, X with 1 and O with -1
board = np.zeros((3,3))

# Function to check if the game has ended or not
def check(board):
    # Check for horizontal, vertical and diagonal lines
    for i in range(3):
        # Check for horizontal lines
        if np.sum(board[i,:]) == 3 or np.sum(board[i,:]) == -3:
            return board[i,0]
        # Check for vertical lines
        if np.sum(board[:,i]) == 3 or np.sum(board[:,i]) == -3:
            return board[0,i]
    # Check for the left diagonal
    if np.sum(np.diag(board)) == 3 or np.sum(np.diag(board)) == -3:
        return board[1,1]
    # Check for the right diagonal
    if np.sum(np.diag(np.fliplr(board))) == 3 or np.sum(np.diag(np.fliplr(board))) == -3:
        return board[1,1]
    # If none of these conditions are satisfied, the game is not over
    return 0

