def knapsack(w, v, W):
    n = len(v)

    # Create a 2D matrix to store values
    table = [[0 for x in range(W + 1)] for y in range(n + 1)]

    # Populate the table values
    for i in range(n + 1):
        for j in range(W + 1):
            if i == 0 or j == 0:
                table[i][j] = 0
            elif w[i - 1] <= j:
                table[i][j] = max(v[i - 1] + table[i - 1][j - w[i - 1]], table[i - 1][j])
            else:
                table[i][j] = table[i - 1][j]

    value = table[n][W]

    # Generate the solution
    x = [False] * n
    i = n
    j = W
    while i > 0 and j > 0:
        if table[i][j] == table[i - 1][j]:
            i -= 1
        else:
            x[i - 1] = True
            j -= w[i - 1]
            i -= 1

    return value, x

